// Formats an integer amount in cents as sign + whole units + '.' + two fraction digits.
// No currency symbol is added. Rounding is unchanged: absolute cents are split with
// floor division by 100 and remainder.
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}

